"use client";

/**
 * Original design and implementation by Gustavo Fior (@gustavo-fior),
 * co-founder Abdul Haidar, and Foglamp Labs. Extracted AS-IS from
 * foglamp-labs/foglamp: apps/web/src/components/marketing/demo/demo-chrome.tsx.
 * Licensed under Apache-2.0.
 */

import { Badge } from "../../../ui/badge";
import { Button } from "../../../ui/button";
import { cn } from "../../../lib/utils";
import {
	IconArrowUpRight,
	IconChevronRight,
	IconCpu,
	IconMessage2Filled,
} from "@tabler/icons-react";
import { useState } from "react";

import { DRAWER_BUTTON_CLASS } from "../../../ui/button-styles";
import { navItem } from "../../../widgets/nav";
import { PageHeader } from "../../../widgets/page-parts";
import {
	isQuickPreset,
	QUICK_PRESETS,
	RangePicker,
	RangePresetButton,
} from "../../../widgets/range-picker";
import { formatModelName, ModelLogo } from "../../../icons/model-logo";
import { resolvePreset } from "../../../lib/range";

import { Piece, useEntering } from "./piece";

// The demo reuses the dashboard's real chrome (Toolbar, SearchInput,
// FilterSelect, SortableHead, PaginationFooter, RangeControl…) directly, since
// those are prop-driven. This file only fills the gaps where the real pieces
// are wired to routing (Link) or app context.

/** The real RangeControl bound to local state — fully interactive, but the
 * mock data doesn't refetch, so it's effectively decorative. Laid out here
 * rather than through RangeControl so each preset chip and the picker is a
 * piece of the hero entrance (see piece.tsx) and lands on its own turn.
 * Outside the entrance a piece renders in place, so the tabs and detail
 * views that mount later look exactly like the real control. */
export function DemoRange() {
	const [range, setRange] = useState(() => resolvePreset("24h"));
	// While the entrance runs, the row keeps 3D so each piece's lift reads.
	const entering = useEntering();
	return (
		<div
			className={cn("flex items-center gap-2", entering && "transform-3d")}
		>
			{QUICK_PRESETS.map((key) => (
				<Piece key={key}>
					<RangePresetButton
						preset={key}
						active={range.key === key}
						onClick={() => setRange(resolvePreset(key))}
					/>
				</Piece>
			))}
			<Piece>
				<RangePicker
					value={range}
					onChange={setRange}
					compact={isQuickPreset(range)}
				/>
			</Piece>
		</div>
	);
}

/** List-page header — the real RouteHeader minus the range context: same
 * PageHeader, section icon looked up from the shared nav config. */
export function DemoListHeader({
	href,
	title,
	withRange,
	actions,
}: {
	href: string;
	title: string;
	withRange?: boolean;
	actions?: React.ReactNode;
}) {
	const item = navItem(href);
	const composedActions =
		withRange || actions ? (
			<>
				{actions}
				{withRange && <DemoRange />}
			</>
		) : undefined;
	return (
		<PageHeader
			title={title}
			icon={item?.icon}
			iconClassName={item?.iconClassName}
			actions={composedActions}
		/>
	);
}

// A `[icon] Parent › Title` breadcrumb header for detail views — PageHeader's
// `back` variant with the Link swapped for a button that pops back to the
// list (no routing in the demo).
export function DetailHeader({
	backHref,
	title,
	titleLeading,
	titleTrailing,
	actions,
	onBack,
}: {
	backHref: string;
	title: string;
	titleLeading?: React.ReactNode;
	titleTrailing?: React.ReactNode;
	actions?: React.ReactNode;
	onBack: () => void;
}) {
	const item = navItem(backHref);
	const BackIcon = item?.icon;
	return (
		<div className="flex flex-wrap items-end justify-between gap-4 px-8 h-8">
			<div className="flex min-w-0 flex-col gap-1.5">
				<h1 className="flex items-center gap-1.5 text-base font-medium tracking-tight">
					<button
						type="button"
						onClick={onBack}
						className="flex shrink-0 cursor-pointer items-center gap-2 text-muted-foreground transition-colors hover:text-foreground"
					>
						{BackIcon && (
							<BackIcon
								className={cn("size-4.5 shrink-0", item?.iconClassName)}
							/>
						)}
						{item?.label}
					</button>
					<IconChevronRight className="size-4 shrink-0 text-muted-foreground/50 stroke-[1.5px]" />
					{titleLeading}
					<span className="truncate">{title}</span>
					{titleTrailing}
				</h1>
			</div>
			{actions && (
				// Nudge actions down so they line up with the title text.
				<div className="flex items-center gap-2 translate-y-1">{actions}</div>
			)}
		</div>
	);
}

/** Linked-entity pill on detail pages — the real ContextChip with the Link
 * swapped for an inert button. */
export function DemoContextChip({
	icon: ChipIcon,
	iconClassName,
	label,
	onClick,
}: {
	icon: React.ComponentType<{ className?: string }>;
	iconClassName?: string;
	label: string;
	onClick?: () => void;
}) {
	return (
		<Button
			variant="outline"
			className="max-w-xs justify-start bg-card hover:bg-muted/50 aria-expanded:bg-muted/50 dark:hover:bg-muted dark:aria-expanded:bg-muted font-normal transition-[color,box-shadow] active:scale-100 dark:border-0 dark:shadow-(--custom-outline-shadow)"
			onClick={onClick}
		>
			<ChipIcon className={cn("size-3.5 shrink-0", iconClassName)} />
			<span className="truncate">{label}</span>
			<IconArrowUpRight className="size-3.5 shrink-0 -ml-0.5 mt-px text-muted-foreground" />
		</Button>
	);
}

/** The runs drawers' "See session" button — the real `SessionButton` with
 * the demo's in-app navigation instead of a link. */
export function DemoSessionButton({ onClick }: { onClick: () => void }) {
	return (
		<Button
			size="sm"
			variant="secondary"
			className={cn("w-fit", DRAWER_BUTTON_CLASS)}
			onClick={onClick}
		>
			<IconMessage2Filled className="text-sky-500" />
			See session
			<IconArrowUpRight className="mt-px" />
		</Button>
	);
}

/** Static context chip for the model(s) a session or trace ran on — the real
 * ModelChip built on DemoContextChip. One model shows its logo and display
 * name; several overlap their logos (capped at three) and read "n models". */
export function DemoModelChip({ models }: { models: string[] }) {
	if (models.length === 0) return null;
	const only = models[0];
	if (models.length === 1 && only) {
		return (
			<DemoContextChip
				icon={(p) => <ModelLogo modelId={only} className={p.className} />}
				iconClassName=""
				label={formatModelName(only)}
			/>
		);
	}
	const shown = models.slice(0, 3);
	return (
		<span title={models.map((m) => formatModelName(m)).join(", ")}>
			<DemoContextChip
				icon={(p) => (
					<span className={cn("flex items-center -space-x-1.5", p.className)}>
						{shown.map((m) => (
							<span
								key={m}
								className="flex size-4 items-center justify-center rounded-full bg-card ring-1 ring-card"
							>
								<ModelLogo modelId={m} className="size-3" />
							</span>
						))}
						{models.length > shown.length && (
							<IconCpu className="size-3 text-muted-foreground" />
						)}
					</span>
				)}
				iconClassName="w-auto"
				label={`${models.length} models`}
			/>
		</span>
	);
}

/** `v3` chip for a run's inferred prompt version — the real PromptVersionChip
 * with its link to the agent page swapped for the demo's in-app navigation. */
export function DemoPromptVersionChip({
	version,
	onClick,
	className,
}: {
	version: { id: string; number: number } | null | undefined;
	onClick?: () => void;
	className?: string;
}) {
	if (!version) return null;
	return (
		<Badge
			variant="sky"
			size="sm"
			className={cn("font-mono normal-case tabular-nums", className)}
			title="Prompt version — see all versions"
			render={<button type="button" onClick={onClick} />}
		>
			{`v${version.number}`}
		</Badge>
	);
}

"use client";

/**
 * Original design and implementation by Gustavo Fior (@gustavo-fior),
 * co-founder Abdul Haidar, and Foglamp Labs. Extracted AS-IS from
 * foglamp-labs/foglamp: apps/web/src/components/marketing/demo/demo-context.tsx.
 * Licensed under Apache-2.0.
 */

import { createContext, useContext } from "react";

import type { DemoTab } from "./mock-data";

export type DetailView =
	| { type: "trace"; id: string }
	| { type: "eval"; id: string }
	| { type: "agent"; id: string }
	| { type: "workflow"; id: string }
	| { type: "session"; id: string }
	| null;

type DemoContextValue = {
	tab: DemoTab;
	// Ignored until the demo is interactive (see DashboardDemo).
	setTab: (tab: DemoTab) => void;
	// False while the hero's entrance is still running: the nav shows its
	// links but does not take a click.
	interactive: boolean;
	detail: DetailView;
	openDetail: (detail: NonNullable<DetailView>) => void;
	closeDetail: () => void;
};

const DemoContext = createContext<DemoContextValue | null>(null);

export function DemoProvider({
	value,
	children,
}: {
	value: DemoContextValue;
	children: React.ReactNode;
}) {
	return <DemoContext.Provider value={value}>{children}</DemoContext.Provider>;
}

export function useDemo() {
	const ctx = useContext(DemoContext);
	if (!ctx) throw new Error("useDemo must be used within <DemoProvider>");
	return ctx;
}

/**
 * Original design and implementation by Gustavo Fior (@gustavo-fior),
 * co-founder Abdul Haidar, and Foglamp Labs. Extracted AS-IS from
 * foglamp-labs/foglamp: apps/web/src/components/marketing/demo/entrance.ts.
 * Licensed under Apache-2.0.
 */
import { type MotionProps, type Variants, stagger } from "motion/react";

// The hero demo's entrance. The chrome frame sits tilted from the first
// paint, and each surface inside it lands on it like a part of a 3D model:
// it starts lifted off the frame's plane and a little further up, then
// settles into place. The inset panel goes first, then the sidebar, then
// the content in the panel. Once the last one has landed, the frame swings
// flat (see Hero). Both files that own a surface share these numbers, so
// the drops match. The lift only reads in 3D, so every ancestor between the
// tilted frame and a surface keeps transform-style: preserve-3d and does
// not clip while the drops run.
//
// The sidebar and the content have no surface of their own. Their pieces
// (nav links, the header, table rows) each make the same drop, one after
// another: the sidebar's pieces land on the chrome, the content's on the
// inset panel. They are Motion variants, so an element only has to be a
// Piece (see piece.tsx) to join in; the wrapper around them (landPieces)
// hands each one its start time and does not move itself.

export const ENTRANCE_EASE: [number, number, number, number] = [
  0.32, 0.72, 0, 1,
];

// The variant names the surfaces, the wrappers, and the pieces share.
export const LIFTED = "lifted";
export const LANDED = "landed";

// Where a surface or a piece starts before it drops: lifted off the plane
// it lands on toward the viewer (z) and a little further up the plane (y),
// in px.
const LIFT = 40;
const DROP = 84;
const DURATION = 1.7;

// The pieces: how far up the plane each starts (it shares LIFT for the
// lift off the plane), how long the drop takes, the gap between one piece
// and the next, and how long after the wrapper's cue the first follows.
const PIECE_DROP = 40;
const PIECE_DURATION = 1.1;
const PIECE_GAP = 0.065;
const PIECE_AFTER = 0.25;

// Seconds after mount that each drop is cued. The chrome's tilt
// is in place by then, and the hero copy is still finishing its rise when
// the sidebar starts, so the two overlap a little.
export const DROP_AT = {
  inset: 0.9,
  sidebar: 1,
  content: 1.8,
} as const;

// How far into the inset surface's drop its colour starts to shift (see
// dropIn). Until then the plate is still the chrome's colour, and it is
// transparent at the start so nothing shows where it hangs above the frame.
const SURFACE_TINT_AT = 0.3;

/** The inset surface's drop, split across two layers because of how the
 * surface appears. It does not simply fade in: in dark mode the surface is
 * only three sRGB levels lighter than the chrome, and a translucent plate
 * blended on the compositor lands on either side of a rounding boundary
 * from frame to frame, which reads as the whole plate flickering while it
 * appears. So the plate fades in (from nothing, so it does not show where
 * it starts above the frame's top edge) while it is still the chrome's
 * own colour, where the blend is exact, and once opaque it shifts colour
 * to its own: an opaque plate rasterises to one exact colour per frame.
 * The shadow does have to fade the whole way, so it sits on a layer of its
 * own (`shadow`); a one-level wobble inside a soft shadow is invisible. The
 * drop is one `transform` string rather than y and z, so the browser runs
 * it off the main thread on the same clock as the fades. Both are nothing
 * under reduced motion. */
export function dropIn(
  delay: number,
  reduce: boolean
): { surface: MotionProps; shadow: MotionProps } {
  if (reduce) return { surface: {}, shadow: {} };
  const transition = { duration: DURATION, ease: ENTRANCE_EASE, delay };
  const split = { ...transition, times: [0, SURFACE_TINT_AT, 1] };
  const surface: Variants = {
    [LIFTED]: {
      opacity: 0,
      backgroundColor: "var(--sidebar)",
      transform: `translateY(${-DROP}px) translateZ(${LIFT}px)`,
    },
    [LANDED]: {
      opacity: [0, 1, 1],
      backgroundColor: ["var(--sidebar)", "var(--sidebar)", "var(--background)"],
      transform: "translateY(0px) translateZ(0px)",
      transition: { ...transition, opacity: split, backgroundColor: split },
    },
  };
  const shadow: Variants = {
    [LIFTED]: { opacity: 0 },
    [LANDED]: { opacity: 1, transition },
  };
  return {
    surface: { initial: LIFTED, animate: LANDED, variants: surface },
    shadow: { initial: LIFTED, animate: LANDED, variants: shadow },
  };
}

/** Motion props for a wrapper whose pieces drop one after another from the
 * given cue, or nothing under reduced motion. The wrapper itself stays put
 * and fully visible; it only passes the variant state and the stagger down
 * to its pieces. The cue's own delay does not reach them, so it is folded
 * into their start. */
export function landPieces(delay: number, reduce: boolean): MotionProps {
  if (reduce) return {};
  const variants: Variants = {
    [LIFTED]: {},
    [LANDED]: {
      transition: {
        delayChildren: stagger(PIECE_GAP, { startDelay: delay + PIECE_AFTER }),
      },
    },
  };
  return { initial: LIFTED, animate: LANDED, variants };
}

/** Variants for one piece: the same drop as a surface. Its wrapper decides
 * when it starts. */
export const PIECE_VARIANTS: Variants = {
  [LIFTED]: { opacity: 0, y: -PIECE_DROP, z: LIFT },
  [LANDED]: {
    opacity: 1,
    y: 0,
    z: 0,
    transition: { duration: PIECE_DURATION, ease: ENTRANCE_EASE },
  },
};

/**
 * Original design and implementation by Gustavo Fior (@gustavo-fior),
 * co-founder Abdul Haidar, and Foglamp Labs. Extracted AS-IS from
 * foglamp-labs/foglamp: apps/web/src/components/marketing/demo/mock-data.ts.
 * Licensed under Apache-2.0.
 */
import { SLOT_LINE } from "../../../lib/prompts/infer";

import { agentColor } from "../../../widgets/leaf/agent-icon";
import type { ChartConfig } from "../../../charts/evilcharts/ui/chart";
import type { PromptVersion } from "../../../widgets/prompt-versions-card";
import type { SlotExamples } from "../../../widgets/prompt-prose";

export type DemoTab =
  | "overview"
  | "workflows"
  | "agents"
  | "sessions"
  | "traces"
  | "evals"
  | "alerts";

// ─────────────────────────────────────────────────────────────────────────────
// Overview — KPI cards, time series, model/agent tables, live feed
// ─────────────────────────────────────────────────────────────────────────────

export type KpiCard = {
  label: string;
  value: string;
  delta: { pct: number; dir: "up" | "down" | "flat" } | null;
  deltaInverted?: boolean;
  hint: string;
};

// The four canonical overview KPIs, in the real dashboard's order
// (Tokens → Total cost → Eval pass rate → Error rate). The overview tab supplies
// each card's icon + bottom chart (sparkline / pill); see OVERVIEW_PASS_RATE /
// OVERVIEW_ERROR_RATE for the pill fractions.
export const KPIS: KpiCard[] = [
  {
    label: "Tokens",
    value: "46.6M",
    delta: { pct: 0.18, dir: "up" },
    hint: "33.9M in · 12.7M out",
  },
  {
    label: "Total cost",
    value: "$840.40",
    delta: { pct: 0.124, dir: "up" },
    deltaInverted: true,
    hint: "~$25.2k/mo",
  },
  {
    label: "Eval pass rate",
    value: "94%",
    delta: { pct: 0.04, dir: "up" },
    hint: "6.1k checks",
  },
  {
    label: "Error rate",
    value: "0.8%",
    delta: { pct: 0.31, dir: "down" },
    deltaInverted: true,
    hint: "162 of 19.6k spans",
  },
];

// Pill-meter fractions for the two ratio KPIs (pass rate, error rate).
export const OVERVIEW_PASS_RATE = 0.94;
export const OVERVIEW_ERROR_RATE = 0.008;

export type CostPoint = {
  label: string;
  "gpt-4o": number;
  "claude-sonnet": number;
  "gpt-4o-mini": number;
};

// 24 hourly buckets, stacked by model. Hand-shaped to look like a real workday
// ramp (quiet overnight, busy midday) rather than random noise.
export const COST_SERIES: CostPoint[] = [
  ["00:00", 4.2, 3.1, 0.8],
  ["02:00", 3.1, 2.4, 0.6],
  ["04:00", 2.8, 2.0, 0.5],
  ["06:00", 5.6, 4.2, 1.1],
  ["08:00", 12.4, 9.8, 2.4],
  ["10:00", 21.6, 16.2, 4.1],
  ["12:00", 28.3, 22.1, 5.6],
  ["14:00", 31.2, 24.8, 6.2],
  ["16:00", 26.7, 20.4, 5.1],
  ["18:00", 18.9, 14.3, 3.6],
  ["20:00", 11.2, 8.7, 2.2],
  ["22:00", 6.8, 5.1, 1.3],
].map(([label, a, b, c]) => ({
  label: label as string,
  "gpt-4o": a as number,
  "claude-sonnet": b as number,
  "gpt-4o-mini": c as number,
}));

export type LatencyPoint = {
  label: string;
  p50: number;
  p95: number;
  p99: number;
};

export const LATENCY_SERIES: LatencyPoint[] = [
  ["00:00", 980, 2400, 3600],
  ["02:00", 920, 2200, 3400],
  ["04:00", 940, 2300, 3500],
  ["06:00", 1050, 2800, 4100],
  ["08:00", 1180, 3200, 4800],
  ["10:00", 1240, 3420, 5100],
  ["12:00", 1310, 3680, 5400],
  ["14:00", 1180, 3420, 5000],
  ["16:00", 1120, 3100, 4600],
  ["18:00", 1040, 2900, 4200],
  ["20:00", 990, 2600, 3800],
  ["22:00", 960, 2450, 3650],
].map(([label, p50, p95, p99]) => ({
  label: label as string,
  p50: p50 as number,
  p95: p95 as number,
  p99: p99 as number,
}));

// ─────────────────────────────────────────────────────────────────────────────
// Overview — full-fidelity time series + ranked breakdowns
// ─────────────────────────────────────────────────────────────────────────────

// `n` hourly ClickHouse datetime strings ('YYYY-MM-DD HH:MM:SS', UTC) ending at
// a fixed recent hour, so makeBucketLabel/formatBucketFull parse them like the
// real timeseries buckets.
function hourBuckets(n: number): string[] {
  const base = new Date("2026-06-15T14:00:00Z").getTime();
  return Array.from({ length: n }, (_, i) => {
    const d = new Date(base - (n - 1 - i) * 3_600_000);
    return d.toISOString().slice(0, 19).replace("T", " ");
  });
}

// 24 hourly buckets shared by every overview/detail trend chart.
const OV_BUCKETS = hourBuckets(24);

// A workday bell over the hour-of-day: ~0 in the small hours, ~1 mid-afternoon.
// Used by the agent/workflow detail trends; the overview series below is
// hand-authored instead.
function wave(hour: number): number {
  return 0.5 - 0.5 * Math.cos(((hour - 3) / 24) * 2 * Math.PI);
}

// Index-seeded jitter in [0,1) — deterministic (no Math.random) so renders are
// stable across reloads.
const jitter = (i: number, seed: number, mod: number) =>
  ((i * seed) % mod) / mod;

export type OverviewPoint = {
  bucket: string;
  requests: number;
  errors: number;
  p50: number;
  p95: number;
  p99: number;
  tokens: number;
  cost: number;
};

// One row per hourly bucket, oldest first (15:00 UTC yesterday → 14:00 UTC
// today), hand-authored so the shape reads like a real day rather than a
// formula: a US-afternoon peak that ebbs into a 03:00–05:00 UTC trough, then
// the European morning ramps back up. Three events break the curve on
// purpose — a retry storm at 18:00 (errors and tail latency jump while
// requests spike on short, failing calls), a nightly batch at 02:00 (few
// requests but huge contexts, so tokens and cost spike while latency climbs),
// and a lone slow call at 04:00 that lifts p99 alone. Tokens per request and
// cost per token drift hour to hour as the model mix shifts, so the sparklines
// don't simply trace the request curve.
//                req  err   p50   p95    p99     tokens  cost
const OV_ROWS: [number, number, number, number, number, number, number][] = [
  /* 15:00 */ [1120, 6, 1120, 3180, 5400, 2_510_000, 47.8],
  /* 16:00 */ [1210, 4, 1210, 3460, 6100, 2_940_000, 54.2],
  /* 17:00 */ [1080, 7, 1090, 3020, 4900, 2_230_000, 42.6],
  /* 18:00 */ [1460, 48, 1640, 6240, 11400, 2_620_000, 61.9],
  /* 19:00 */ [1150, 21, 1380, 4410, 8300, 2_710_000, 49.3],
  /* 20:00 */ [990, 5, 1050, 2960, 5200, 2_080_000, 39.1],
  /* 21:00 */ [1050, 3, 1130, 3310, 5600, 2_460_000, 44.7],
  /* 22:00 */ [760, 4, 960, 2620, 4300, 1_520_000, 30.4],
  /* 23:00 */ [610, 2, 890, 2410, 4800, 1_410_000, 25.9],
  /* 00:00 */ [480, 3, 840, 2280, 3700, 930_000, 16.2],
  /* 01:00 */ [420, 1, 810, 2190, 4100, 880_000, 14.8],
  /* 02:00 */ [530, 12, 1920, 5080, 8200, 4_760_000, 41.6],
  /* 03:00 */ [310, 2, 790, 2050, 3300, 610_000, 10.9],
  /* 04:00 */ [290, 0, 830, 2340, 5600, 670_000, 12.4],
  /* 05:00 */ [340, 1, 800, 2110, 3500, 620_000, 10.1],
  /* 06:00 */ [410, 3, 870, 2380, 3900, 950_000, 19.3],
  /* 07:00 */ [620, 2, 940, 2610, 4200, 1_380_000, 27.6],
  /* 08:00 */ [840, 5, 1010, 2830, 4700, 1_710_000, 33.2],
  /* 09:00 */ [910, 4, 1060, 2920, 5300, 2_240_000, 42.8],
  /* 10:00 */ [1060, 7, 1180, 3390, 5900, 2_180_000, 40.1],
  /* 11:00 */ [980, 3, 1090, 3070, 4800, 2_350_000, 45.9],
  /* 12:00 */ [870, 6, 1020, 2780, 4600, 1_690_000, 32.3],
  /* 13:00 */ [960, 5, 1150, 3240, 6400, 2_310_000, 43.6],
  /* 14:00 */ [1190, 8, 1230, 3520, 5800, 2_830_000, 53.7],
];

export const OVERVIEW_SERIES: OverviewPoint[] = OV_BUCKETS.map((bucket, i) => {
  const [requests, errors, p50, p95, p99, tokens, cost] = OV_ROWS[i]!;
  return { bucket, requests, errors, p50, p95, p99, tokens, cost };
});

// Per-model cost over time (m0 gpt-5.6-sol / m1 claude-fable-5 / m2
// gemini-3.5-flash / m3 glm-5 / m4 minimax-m2.5), derived from the overview
// cost so the bars and the "Models" breakdown agree.
export type OverviewCostPoint = {
  bucket: string;
  m0: number;
  m1: number;
  m2: number;
  m3: number;
  m4: number;
};

// Sine-hash noise in [0,1): stable per (bucket, seed) so renders never shift,
// but jagged enough to read as real traffic instead of a smooth formula.
const costNoise = (i: number, seed: number) => {
  const x = Math.sin(i * 127.1 + seed * 311.7) * 43758.5453;
  return x - Math.floor(x);
};

// Baseline model mix by cost share (matches the "Models" breakdown ranking).
const COST_MIX = [0.42, 0.3, 0.13, 0.09, 0.06];

// Hours whose mix deliberately departs from the baseline: the 18:00 retry
// storm (bucket 3) hammered gpt-5.6-sol, and the 02:00 batch (bucket 11) ran
// mostly on gemini-3.5-flash.
const COST_MIX_OVERRIDES: Record<number, number[]> = {
  3: [0.61, 0.22, 0.08, 0.05, 0.04],
  11: [0.14, 0.12, 0.58, 0.1, 0.06],
};

export const OVERVIEW_COST_SERIES: OverviewCostPoint[] = OVERVIEW_SERIES.map(
  (r, i) => {
    // Jostle each model's share around its baseline, then normalise so the
    // stack sums exactly to the hour's cost — the bars and the total-cost
    // sparkline tell the same story.
    const base = COST_MIX_OVERRIDES[i] ?? COST_MIX;
    const raw = base.map(
      (share, m) => share * (0.7 + 0.6 * costNoise(i, m + 1))
    );
    const total = raw.reduce((a, b) => a + b, 0);
    const part = (m: number) => +((r.cost * raw[m]!) / total).toFixed(3);
    return {
      bucket: r.bucket,
      m0: part(0),
      m1: part(1),
      m2: part(2),
      m3: part(3),
      m4: part(4),
    };
  }
);

