import * as React from "react";

type FoglampLinkComponent = React.ElementType;

const FoglampLinkContext = React.createContext<FoglampLinkComponent>("a");

export type FoglampLinkProviderProps = {
	/** Router or link component that should render every FoglampLink below it. */
	component: FoglampLinkComponent;
	children: React.ReactNode;
};

export function FoglampLinkProvider({
	component,
	children,
}: FoglampLinkProviderProps) {
	return (
		<FoglampLinkContext.Provider value={component}>
			{children}
		</FoglampLinkContext.Provider>
	);
}

/**
 * A link with no wrapper of its own. The provider component receives the
 * original props directly, so the rendered DOM and styling stay with the
 * router's link implementation. A per-link component or `as` can override it.
 */
export type FoglampLinkProps<Component extends FoglampLinkComponent = "a"> =
	React.ComponentPropsWithRef<Component> & {
		component?: Component;
		as?: Component;
		/** Common router destination prop, available with the default anchor type. */
		to?: string;
	};

export function FoglampLink<Component extends FoglampLinkComponent = "a">({
	component,
	as,
	...props
}: FoglampLinkProps<Component>) {
	const providerComponent = React.useContext(FoglampLinkContext);
	const LinkComponent = component ?? as ?? providerComponent;

	return React.createElement(LinkComponent, props as React.ComponentPropsWithRef<Component>);
}

/**
 * Original design by Gustavo Fior (@gustavo-fior) and Foglamp Labs,
 * co-founded by Abdul Haidar. Extracted AS-IS from foglamp-labs/foglamp.
 */

// Line diff (LCS). Used by version inference to align a prompt against the
// canonical prompt of its family, and by the dashboard to show a version's
// template against the previous one. Prompts are small (hundreds of lines), so
// a plain O(n·m) table is fine; oversized inputs fall back to prefix/suffix
// trimming with the middle reported as one replacement.

export type DiffOp = { type: "same" | "add" | "del"; line: string };

const MAX_CELLS = 4_000_000;

export function lineDiff(a: string, b: string): DiffOp[] {
  return diffLines(a.split("\n"), b.split("\n"));
}

export function diffLines(a: string[], b: string[]): DiffOp[] {
  // Trim the common prefix/suffix first — most prompt variants differ in a few
  // lines, so this keeps the table tiny.
  let start = 0;
  while (start < a.length && start < b.length && a[start] === b[start]) start++;
  let endA = a.length;
  let endB = b.length;
  while (endA > start && endB > start && a[endA - 1] === b[endB - 1]) {
    endA--;
    endB--;
  }
  const ops: DiffOp[] = [];
  for (let i = 0; i < start; i++) ops.push({ type: "same", line: a[i] as string });

  const midA = a.slice(start, endA);
  const midB = b.slice(start, endB);
  if (midA.length * midB.length > MAX_CELLS) {
    for (const line of midA) ops.push({ type: "del", line });
    for (const line of midB) ops.push({ type: "add", line });
  } else {
    ops.push(...lcsDiff(midA, midB));
  }

  for (let i = endA; i < a.length; i++) ops.push({ type: "same", line: a[i] as string });
  return ops;
}

function lcsDiff(a: string[], b: string[]): DiffOp[] {
  const n = a.length;
  const m = b.length;
  if (n === 0) return b.map((line) => ({ type: "add" as const, line }));
  if (m === 0) return a.map((line) => ({ type: "del" as const, line }));
  // dp[i][j] = LCS length of a[i..] and b[j..]
  const width = m + 1;
  const dp = new Uint32Array((n + 1) * width);
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      dp[i * width + j] =
        a[i] === b[j]
          ? (dp[(i + 1) * width + j + 1] as number) + 1
          : Math.max(dp[(i + 1) * width + j] as number, dp[i * width + j + 1] as number);
    }
  }
  const ops: DiffOp[] = [];
  let i = 0;
  let j = 0;
  while (i < n && j < m) {
    if (a[i] === b[j]) {
      ops.push({ type: "same", line: a[i] as string });
      i++;
      j++;
    } else if ((dp[(i + 1) * width + j] as number) >= (dp[i * width + j + 1] as number)) {
      ops.push({ type: "del", line: a[i] as string });
      i++;
    } else {
      ops.push({ type: "add", line: b[j] as string });
      j++;
    }
  }
  while (i < n) ops.push({ type: "del", line: a[i++] as string });
  while (j < m) ops.push({ type: "add", line: b[j++] as string });
  return ops;
}

/**
 * How alike two prompts are, 0..1: shared lines count fully, and replaced
 * lines count by how many words they keep (so a prompt whose only change is a
 * name inside one line still scores high). Symmetric, order-aware.
 */
export function sequenceSimilarity(a: string[], b: string[]): number {
  const longest = Math.max(a.length, b.length);
  if (longest === 0) return 1;
  const ops = diffLines(a, b);
  let credit = 0;
  let k = 0;
  while (k < ops.length) {
    const op = ops[k] as DiffOp;
    if (op.type === "same") {
      credit += 1;
      k++;
      continue;
    }
    const del: string[] = [];
    const add: string[] = [];
    while (k < ops.length && (ops[k] as DiffOp).type !== "same") {
      const h = ops[k] as DiffOp;
      (h.type === "del" ? del : add).push(h.line);
      k++;
    }
    if (del.length > 0 && add.length > 0) {
      credit += wordSimilarity(del.join(" "), add.join(" ")) * ((del.length + add.length) / 2);
    }
  }
  return Math.min(1, credit / longest);
}

const MAX_WORDS = 400;

function wordSimilarity(a: string, b: string): number {
  const wa = a.split(/\s+/).filter(Boolean).slice(0, MAX_WORDS);
  const wb = b.split(/\s+/).filter(Boolean).slice(0, MAX_WORDS);
  const longest = Math.max(wa.length, wb.length);
  if (longest === 0) return 1;
  const same = diffLines(wa, wb).filter((op) => op.type === "same").length;
  return same / longest;
}

/**
 * Original design by Gustavo Fior (@gustavo-fior) and Foglamp Labs,
 * co-founded by Abdul Haidar. Extracted AS-IS from foglamp-labs/foglamp.
 */

import { diffLines, sequenceSimilarity } from "./diff";

// Prompt version inference. Input: one row per distinct normalized prompt an
// agent has run with (its hash, text, when it was first/last seen, run count).
// Output: versions — groups of hashes that share a template, ordered by first
// appearance. Nothing here is declared by the user; versions are read off the
// runs.
//
// Two kinds of variation show up between an agent's prompts:
//   • slots — dynamic content the normalizer didn't catch (a user's name, a
//     retrieved snippet). Values interleave in time and differ from each other.
//   • edits — someone changed the prompt. The new text replaces the old one
//     cleanly in time and every later run carries it.
// A prompt joins the current version when it only differs at positions that
// already vary within it, or when it overlaps the version in time. Otherwise it
// is held as a cut candidate until enough runs share the same new text.

export type PromptSample = {
  hash: string;
  /** Normalized prompt text (see normalizePrompt). */
  text: string;
  firstSeen: Date;
  lastSeen: Date;
  runs: number;
};

export type InferredVersion = {
  /** Canonical prompt with varying stretches replaced by a `{…}` line. */
  template: string;
  /** Member hashes, oldest first. */
  hashes: string[];
  /** Number of varying stretches in the template. */
  slotCount: number;
  runs: number;
  firstSeen: Date;
  lastSeen: Date;
};

export type InferOptions = {
  /** Runs a new prompt text needs before it counts as a new version. */
  minRuns?: number;
  /** Overlap tolerated between an old and a new version (rolling deploys). */
  graceMs?: number;
  /** Text similarity below which prompts are unrelated (separate families). */
  similarity?: number;
};

const DEFAULTS: Required<InferOptions> = {
  minRuns: 3,
  graceMs: 5 * 60 * 1000,
  similarity: 0.6,
};

/** The template line standing in for content that varies between runs. */
export const SLOT_LINE = "{…}";

// A member's text expressed in the coordinates of its family's canonical
// prompt: a map from hunk anchor → hunk content. Keys are `rep:<i>` (replaces
// canonical lines starting at i) and `ins:<i>` (inserted before canonical line
// i). A member identical to the canonical has an empty map; "=" below stands
// for "same as canonical" at a position.
type Aligned = Map<string, string>;
const SAME = "=";

type Member = PromptSample & { lines: string[]; aligned: Aligned };

type Family = { canonical: Member; members: Member[] };

export function inferVersions(
  samples: PromptSample[],
  options: InferOptions = {},
): InferredVersion[] {
  const opts = { ...DEFAULTS, ...options };
  const versions: InferredVersion[] = [];
  for (const family of clusterFamilies(samples, opts.similarity)) {
    for (const group of splitFamily(family, opts)) versions.push(render(family, group));
  }
  versions.sort((a, b) => a.firstSeen.getTime() - b.firstSeen.getTime());
  return versions;
}

// --- families ---------------------------------------------------------------

function clusterFamilies(samples: PromptSample[], threshold: number): Family[] {
  // Most-run first so each family's canonical is its most representative text.
  const ordered = [...samples].sort((a, b) => b.runs - a.runs);
  const families: { canonical: PromptSample; lines: string[]; members: PromptSample[] }[] = [];
  for (const s of ordered) {
    const lines = s.text.split("\n");
    let best: (typeof families)[number] | undefined;
    let bestScore = 0;
    for (const f of families) {
      const score = sequenceSimilarity(f.lines, lines);
      if (score > bestScore) {
        bestScore = score;
        best = f;
      }
    }
    if (best && bestScore >= threshold) best.members.push(s);
    else families.push({ canonical: s, lines, members: [s] });
  }
  return families.map((f) => {
    const members = f.members.map((s) => {
      const lines = s.text.split("\n");
      return { ...s, lines, aligned: align(f.lines, lines) };
    });
    const canonical = members.find((m) => m.hash === f.canonical.hash) as Member;
    return { canonical, members };
  });
}

// --- alignment --------------------------------------------------------------

function align(canonical: string[], lines: string[]): Aligned {
  const ops = diffLines(canonical, lines);
  const out: Aligned = new Map();
  let i = 0; // index into canonical
  let k = 0;
  while (k < ops.length) {
    const op = ops[k] as (typeof ops)[number];
    if (op.type === "same") {
      i++;
      k++;
      continue;
    }
    // A hunk: a maximal run of del/add ops. Anchor at the first deleted
    // canonical line, or as an insertion before the next canonical line.
    const anchor = i;
    let deleted = 0;
    const added: string[] = [];
    while (k < ops.length && (ops[k] as (typeof ops)[number]).type !== "same") {
      const h = ops[k] as (typeof ops)[number];
      if (h.type === "del") deleted++;
      else added.push(h.line);
      k++;
    }
    i += deleted;
    const key = deleted > 0 ? `rep:${anchor}` : `ins:${anchor}`;
    out.set(key, `${deleted}\n${added.join("\n")}`);
  }
  return out;
}

function valueAt(m: Member, key: string): string {
  return m.aligned.get(key) ?? SAME;
}

// --- splitting a family into versions ---------------------------------------

class Group {
  members: Member[] = [];
  /** Distinct values seen at each position across the group. */
  values = new Map<string, Set<string>>();
  lastSeen = 0;

  add(m: Member) {
    this.members.push(m);
    this.lastSeen = Math.max(this.lastSeen, m.lastSeen.getTime());
    // Positions this member touches, plus positions the group already tracks
    // (where this member is "=" if it has no entry).
    for (const key of m.aligned.keys()) this.note(key, valueAt(m, key));
    for (const key of this.values.keys()) this.note(key, valueAt(m, key));
  }

  private note(key: string, value: string) {
    let set = this.values.get(key);
    if (!set) {
      set = new Set<string>();
      // Earlier members had no entry here → they were all "=".
      if (this.members.length > 1) set.add(SAME);
      this.values.set(key, set);
    }
    set.add(value);
  }

  /** Positions where the group is unanimous but `m` carries something else. */
  disagreements(m: Member): string[] {
    const out: string[] = [];
    const keys = new Set<string>([...this.values.keys(), ...m.aligned.keys()]);
    for (const key of keys) {
      const set = this.values.get(key);
      const unanimous = set === undefined ? SAME : set.size === 1 ? [...set][0] : undefined;
      if (unanimous === undefined) continue;
      if (valueAt(m, key) !== unanimous) out.push(key);
    }
    return out;
  }
}

function splitFamily(family: Family, opts: Required<InferOptions>): Member[][] {
  const members = [...family.members].sort(
    (a, b) => a.firstSeen.getTime() - b.firstSeen.getTime() || b.runs - a.runs,
  );
  const groups: Member[][] = [];
  let current = new Group();
  // Clean-cut candidates that don't have enough runs yet to open a version.
  let pending: { member: Member; diffs: string[] }[] = [];

  for (const m of members) {
    if (current.members.length === 0) {
      current.add(m);
      continue;
    }
    const diffs = current.disagreements(m);
    // Fits the template (only differs where the version already varies), or
    // overlaps the version in time → dynamic content, same version.
    if (diffs.length === 0 || current.lastSeen > m.firstSeen.getTime() + opts.graceMs) {
      current.add(m);
      continue;
    }
    pending.push({ member: m, diffs });
    // Pending prompts that share one of this prompt's new values are the same
    // edit (a templated prompt's new version shows up as several hashes).
    const shared = pending.filter(
      (p) => p.member === m || diffs.some((k) => valueAt(p.member, k) === valueAt(m, k)),
    );
    const runs = shared.reduce((n, p) => n + p.member.runs, 0);
    // A lone new text among many unrelated pending ones is a slot value that
    // happened to recur, not an edit — unless it is the only candidate.
    const established = runs >= opts.minRuns && (shared.length >= 2 || pending.length === 1);
    if (!established) continue;

    const sharedSet = new Set(shared.map((p) => p.member));
    for (const p of pending) if (!sharedSet.has(p.member)) current.add(p.member);
    groups.push(current.members);
    current = new Group();
    for (const p of shared) current.add(p.member);
    pending = [];
  }
  for (const p of pending) current.add(p.member);
  if (current.members.length > 0) groups.push(current.members);
  return groups;
}

// --- rendering --------------------------------------------------------------

function render(family: Family, members: Member[]): InferredVersion {
  const canonical = members.reduce((best, m) => (m.runs > best.runs ? m : best), members[0] as Member);
  // Re-align against this version's own canonical so the template reads as
  // the most-run prompt with only this version's variation blanked out.
  const aligned =
    canonical === family.canonical
      ? members.map((m) => m.aligned)
      : members.map((m) => align(canonical.lines, m.lines));
  const values = new Map<string, Set<string>>();
  for (const a of aligned) {
    for (const [key, value] of a) {
      let set = values.get(key);
      if (!set) {
        set = new Set([SAME]);
        values.set(key, set);
      }
      set.add(value);
    }
  }
  // Varying positions: replaced canonical lines and insertion points.
  const replaced = new Set<number>();
  const inserts = new Set<number>();
  for (const [key, set] of values) {
    if (set.size < 2) continue;
    const idx = Number(key.slice(4));
    if (key.startsWith("rep:")) {
      let span = 1;
      for (const v of set) if (v !== SAME) span = Math.max(span, Number(v.split("\n", 1)[0]) || 1);
      for (let i = idx; i < idx + span; i++) replaced.add(i);
    } else inserts.add(idx);
  }
  const out: string[] = [];
  let slotCount = 0;
  const pushSlot = () => {
    if (out[out.length - 1] !== SLOT_LINE) {
      out.push(SLOT_LINE);
      slotCount++;
    }
  };
  for (let i = 0; i <= canonical.lines.length; i++) {
    if (inserts.has(i)) pushSlot();
    if (i === canonical.lines.length) break;
    if (replaced.has(i)) pushSlot();
    else out.push(canonical.lines[i] as string);
  }

  const ordered = [...members].sort((a, b) => a.firstSeen.getTime() - b.firstSeen.getTime());
  return {
    template: out.join("\n"),
    hashes: ordered.map((m) => m.hash),
    slotCount,
    runs: members.reduce((n, m) => n + m.runs, 0),
    firstSeen: new Date(Math.min(...members.map((m) => m.firstSeen.getTime()))),
    lastSeen: new Date(Math.max(...members.map((m) => m.lastSeen.getTime()))),
  };
}

/* Original design and implementation by Gustavo Fior (@gustavo-fior), with co-founder Abdul Haidar at Foglamp Labs.
 * Extracted from .reference/foglamp/apps/web/src/lib/range.ts; derived here under Apache-2.0.
 */
import {
  endOfDay,
  endOfMonth,
  format,
  startOfDay,
  startOfMonth,
  subDays,
  subHours,
  subMonths,
} from "date-fns";

export type RangeValue = {
  /** Originating preset key, or "custom" for a calendar-selected range. */
  key: string;
  label: string;
  from: Date;
  to: Date;
};

type Preset = {
  key: string;
  label: string;
  resolve: (now: Date) => { from: Date; to: Date };
};

export const RANGE_PRESETS: Preset[] = [
  {
    key: "1h",
    label: "Last hour",
    resolve: (n) => ({ from: subHours(n, 1), to: n }),
  },
  {
    key: "24h",
    label: "Last 24 hours",
    resolve: (n) => ({ from: subHours(n, 24), to: n }),
  },
  {
    key: "3d",
    label: "Last 3 days",
    resolve: (n) => ({ from: subDays(n, 3), to: n }),
  },
  {
    key: "7d",
    label: "Last 7 days",
    resolve: (n) => ({ from: subDays(n, 7), to: n }),
  },
  {
    key: "30d",
    label: "Last 30 days",
    resolve: (n) => ({ from: subDays(n, 30), to: n }),
  },
  {
    key: "90d",
    label: "Last 90 days",
    resolve: (n) => ({ from: subDays(n, 90), to: n }),
  },
  {
    key: "today",
    label: "Today",
    resolve: (n) => ({ from: startOfDay(n), to: n }),
  },
  {
    key: "month",
    label: "This month",
    resolve: (n) => ({ from: startOfMonth(n), to: n }),
  },
  {
    key: "lastMonth",
    label: "Last month",
    resolve: (n) => {
      const start = startOfMonth(subMonths(n, 1));
      return { from: start, to: endOfMonth(start) };
    },
  },
];

export function resolvePreset(key: string, now: Date = new Date()): RangeValue {
  const p = RANGE_PRESETS.find((x) => x.key === key) ?? RANGE_PRESETS[1]!;
  const { from, to } = p.resolve(now);
  return { key: p.key, label: p.label, from, to };
}

export function defaultRange(): RangeValue {
  return resolvePreset("24h");
}

/** A calendar-selected absolute range (whole days, inclusive of the end day). */
export function customRange(from: Date, to: Date): RangeValue {
  const f = startOfDay(from);
  const t = endOfDay(to);
  return { key: "custom", label: formatRangeLabel(f, t), from: f, to: t };
}

/** An absolute range at full time precision — produced by dragging a zoom
 * selection on a chart (and used to restore stored custom ranges verbatim).
 * Whole-day ranges keep the calendar picker's date-only label. */
export function exactRange(from: Date, to: Date): RangeValue {
  return { key: "custom", label: formatExactLabel(from, to), from, to };
}

function formatExactLabel(from: Date, to: Date): string {
  const wholeDays =
    from.getTime() === startOfDay(from).getTime() &&
    to.getTime() === endOfDay(to).getTime();
  if (wholeDays) return formatRangeLabel(from, to);
  const sameDay = startOfDay(from).getTime() === startOfDay(to).getTime();
  if (sameDay) return `${format(from, "MMM d, HH:mm")} – ${format(to, "HH:mm")}`;
  const sameYear = from.getFullYear() === to.getFullYear();
  const fmt = sameYear ? "MMM d, HH:mm" : "MMM d, yyyy HH:mm";
  return `${format(from, fmt)} – ${format(to, fmt)}`;
}

/** Absolute readout of a resolved window, minute precision — "Aug 10, 14:32 –
 * Aug 11, 14:32". The year only appears when it isn't the current one. */
export function formatRangeWindow(
  from: Date,
  to: Date,
  now: Date = new Date()
): string {
  const fmt = (d: Date) =>
    format(
      d,
      d.getFullYear() === now.getFullYear()
        ? "MMM d, HH:mm"
        : "MMM d, yyyy, HH:mm"
    );
  return `${fmt(from)} to ${fmt(to)}`;
}

export function formatRangeLabel(from: Date, to: Date): string {
  const sameDay = startOfDay(from).getTime() === startOfDay(to).getTime();
  if (sameDay) return format(from, "MMM d, yyyy");
  const sameYear = from.getFullYear() === to.getFullYear();
  return `${format(from, sameYear ? "MMM d" : "MMM d, yyyy")} – ${format(
    to,
    "MMM d, yyyy"
  )}`;
}

