/** One column of a `TableRowsSkeleton` row. Omit `w` for an empty cell (e.g.
 * an actions column). `icon` adds a small square blob before the text blob. */
export type SkeletonCol = {
  w?: string;
  align?: "left" | "right";
  icon?: boolean;
  /** Width class for a second, smaller meta line under the main blob —
   * for two-line details cells (traces/sessions). The two lines reproduce
   * the real cell's line boxes (h-5 name + gap-1 + mt-0.5 + h-4 meta), so
   * the skeleton row height matches the data rows without hardcoding it. */
  sub?: string;
};

/**
 * Placeholder body rows for a list table while its query is in flight. The
 * page's chrome (toolbar, column headers) renders immediately; only these
 * rows shimmer, one blob per column, mirroring the real cells' alignment.
 * Pair with a `table-fixed` Table so the skeleton→data swap can't shift
 * column widths.
 */
export function TableRowsSkeleton({
  rows = 3,
  cols,
  rowHeight = "h-12",
}: {
  rows?: number;
  cols: readonly SkeletonCol[];
  /** Height class matching the real rows, when they're taller than the
   * standard h-12 (e.g. two-line cells). */
  rowHeight?: string;
}) {
  return (
    <>
      {Array.from({ length: rows }).map((_, i) => (
        <TableRow key={i}>
          {cols.map((c, j) => (
            <TableCell key={j} align={c.align} className={rowHeight}>
              {c.sub ? (
                <div className="flex flex-col gap-1">
                  <div className="flex h-5 items-center gap-2">
                    {c.icon && (
                      <Skeleton className="size-4 shrink-0 rounded-md" />
                    )}
                    <Skeleton className={cn("h-4", c.w)} />
                  </div>
                  <div className="mt-0.5 flex h-4 items-center">
                    <Skeleton className={cn("h-3", c.sub)} />
                  </div>
                </div>
              ) : (
                c.w && (
                  <div
                    className={cn(
                      "flex items-center gap-2",
                      c.align === "right" && "justify-end"
                    )}
                  >
                    {c.icon && (
                      <Skeleton className="size-4 shrink-0 rounded-md" />
                    )}
                    <Skeleton className={cn("h-4", c.w)} />
                  </div>
                )
              )}
            </TableCell>
          ))}
        </TableRow>
      ))}
    </>
  );
}

export function TableSkeleton({ rows = 5 }: { rows?: number }) {
  return (
    <div className="flex flex-col gap-3">
      <Skeleton className="h-8 w-1/3" />
      <Skeleton className="h-12 w-full" />
      {Array.from({ length: rows }).map((_, i) => (
        <Skeleton key={i} className="h-7 w-full" />
      ))}
    </div>
  );
}

export function CardsSkeleton({ count = 4 }: { count?: number }) {
  return (
    <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-5">
      {Array.from({ length: count }).map((_, i) => (
        <Skeleton key={i} className="h-24 w-full" />
      ))}
    </div>
  );
}

"use client";

/** Original design by Gustavo Fior (@gustavo-fior), Abdul Haidar and Foglamp Labs.
 * Extracted from foglamp-labs/foglamp under the Apache-2.0 license. */

import { SLOT_LINE } from "../lib/prompts/infer";
import {
  HoverCard,
  HoverCardContent,
  HoverCardTrigger,
} from "../ui/hover-card";
import { IconFileHorizontalFilled } from "@tabler/icons-react";
import { Fragment, useMemo } from "react";

import { formatCount } from "../lib/format";
import { cn } from "../lib/utils";

// A prompt template rendered as the document it is, not as source: headings,
// lists and paragraphs in the reading face, the normalizer's placeholders
// ({date}, {id}, …) as quiet tokens, and each `{…}` slot as a chip that shows
// what runs actually put there. Deliberately not a markdown engine — prompts
// lean on <tags> and literal text that a real parser would swallow, so every
// line the parser doesn't recognise is shown as-is.

type Block =
  | { type: "heading"; level: number; text: string }
  | { type: "paragraph"; lines: string[] }
  | { type: "list"; ordered: boolean; items: string[] }
  | { type: "tag"; text: string }
  | { type: "rule" }
  | { type: "slot"; index: number };

const HEADING = /^(#{1,6})\s+(.*)$/;
const BULLET = /^[-*•]\s+(.*)$/;
// Numbers are normalized to {n}, so "1. Rule" reaches us as "{n}. Rule".
const ORDERED = /^(?:\d+|\{n\})[.)]\s+(.*)$/;
const TAG = /^<\/?[A-Za-z_][\w:-]*(?:\s[^<>]*)?>$/;
const RULE = /^(?:-{3,}|\*{3,}|_{3,})$/;

function isSpecial(line: string): boolean {
  return (
    line === "" ||
    line === SLOT_LINE ||
    HEADING.test(line) ||
    RULE.test(line) ||
    TAG.test(line) ||
    BULLET.test(line) ||
    ORDERED.test(line)
  );
}

export function parsePrompt(template: string): Block[] {
  const blocks: Block[] = [];
  const lines = template.split("\n");
  let slots = 0;
  let i = 0;
  while (i < lines.length) {
    const line = lines[i] as string;
    if (line === "") {
      i++;
      continue;
    }
    if (line === SLOT_LINE) {
      blocks.push({ type: "slot", index: slots++ });
      i++;
      continue;
    }
    const heading = HEADING.exec(line);
    if (heading) {
      blocks.push({
        type: "heading",
        level: (heading[1] as string).length,
        text: heading[2] as string,
      });
      i++;
      continue;
    }
    if (RULE.test(line)) {
      blocks.push({ type: "rule" });
      i++;
      continue;
    }
    if (TAG.test(line)) {
      blocks.push({ type: "tag", text: line });
      i++;
      continue;
    }
    if (BULLET.test(line) || ORDERED.test(line)) {
      const ordered = ORDERED.test(line);
      const re = ordered ? ORDERED : BULLET;
      const items: string[] = [];
      while (i < lines.length) {
        const item = re.exec(lines[i] as string);
        if (!item) break;
        items.push(item[1] as string);
        i++;
      }
      blocks.push({ type: "list", ordered, items });
      continue;
    }
    const para: string[] = [];
    while (i < lines.length && !isSpecial(lines[i] as string)) {
      para.push(lines[i] as string);
      i++;
    }
    blocks.push({ type: "paragraph", lines: para });
  }
  return blocks;
}

// --- inline -----------------------------------------------------------------

const INLINE = /(\*\*[^*\n]+\*\*|`[^`\n]+`|\{(?:date|time|id|email|url|n)\})/g;

const PLACEHOLDER_TITLE: Record<string, string> = {
  date: "A date — differs per run, so it isn't part of the version",
  time: "A clock time — differs per run, so it isn't part of the version",
  id: "An identifier — differs per run, so it isn't part of the version",
  email: "An email address — differs per run, so it isn't part of the version",
  url: "A URL — differs per run, so it isn't part of the version",
  n: "A number — differs per run, so it isn't part of the version",
};

function Inline({ text }: { text: string }) {
  const parts = text.split(INLINE);
  return (
    <>
      {parts.map((part, i) => {
        // split() with one capture group: matches sit at the odd indices.
        const key = `${i}:${part}`;
        if (i % 2 === 0) return <Fragment key={key}>{part}</Fragment>;
        if (part.startsWith("**")) {
          return (
            <strong key={key} className="font-semibold">
              {part.slice(2, -2)}
            </strong>
          );
        }
        if (part.startsWith("`")) {
          return (
            <code
              key={key}
              className="rounded bg-muted px-1 py-px font-mono text-[0.85em]"
            >
              {part.slice(1, -1)}
            </code>
          );
        }
        const name = part.slice(1, -1);
        return (
          <span
            key={key}
            className="rounded bg-lime-400/20 px-1 py-px font-mono text-[0.8em] text-lime-700 dark:bg-lime-600/25 dark:text-lime-300"
            title={PLACEHOLDER_TITLE[name]}
          >
            {part}
          </span>
        );
      })}
    </>
  );
}

// --- slots ------------------------------------------------------------------

export type SlotExample = { value: string; runs: number };
/** Per-slot examples, in slot order — the shape agents.promptSlotExamples returns. */
export type SlotExamples = { slots: { examples: SlotExample[] }[] };

function SlotChip({
  index,
  count,
  examples,
  loading,
}: {
  index: number;
  count: number;
  examples: SlotExample[] | undefined;
  loading: boolean;
}) {
  return (
    <HoverCard>
      <HoverCardTrigger
        delay={200}
        render={<button type="button" />}
        className="inline-flex cursor-default items-center gap-1 rounded-md bg-lime-400 px-1.5 py-0.5 text-[11px] font-medium text-lime-950 transition-colors hover:bg-lime-300 dark:bg-lime-600 dark:hover:bg-lime-500"
      >
        <IconFileHorizontalFilled className="size-3 text-lime-950/70" />
        varies per run
      </HoverCardTrigger>
      <HoverCardContent side="bottom" align="start" className="w-80 p-0">
        <div className="border-b border-border/60 px-3 py-2 text-xs text-muted-foreground">
          Slot {index + 1} of {count} · what runs put here
        </div>
        {loading ? (
          <div className="px-3 py-2.5 text-xs text-muted-foreground">
            Loading examples…
          </div>
        ) : !examples || examples.length === 0 ? (
          <div className="px-3 py-2.5 text-xs text-muted-foreground">
            No example could be read for this slot yet.
          </div>
        ) : (
          <ul className="max-h-72 divide-y divide-border/40 overflow-auto">
            {examples.map((e) => (
              <li key={e.value} className="px-3 py-2">
                <div className="mb-1 text-[10px] tabular-nums text-muted-foreground">
                  {formatCount(e.runs)} {e.runs === 1 ? "run" : "runs"}
                </div>
                <div className="line-clamp-6 font-mono text-[11px] leading-relaxed whitespace-pre-wrap wrap-anywhere">
                  {e.value === "" ? (
                    <span className="italic text-muted-foreground">
                      nothing — the line is absent in these runs
                    </span>
                  ) : (
                    e.value
                  )}
                </div>
              </li>
            ))}
          </ul>
        )}
      </HoverCardContent>
    </HoverCard>
  );
}

