export function PromptProse({ template, slots, loading, className }: {
  template: string; versionId?: string; slotCount?: number;
  slots?: SlotExamples; loading?: boolean; className?: string;
}) {
  return <PromptProseView template={template} slots={slots} loading={loading} className={className} />;
}

/** The prose rendering alone, fed its slot examples — so the marketing demo
 * can show a template without the query. */
export function PromptProseView({
  template,
  slots,
  loading = false,
  className,
}: {
  template: string;
  slots: SlotExamples | undefined;
  loading?: boolean;
  className?: string;
}) {
  const blocks = useMemo(() => parsePrompt(template), [template]);
  // "Slot 2 of 3" — the count is the number of slot lines in the template.
  const slotCount = useMemo(
    () => blocks.filter((b) => b.type === "slot").length,
    [blocks],
  );
  return (
    <div className={cn("flex flex-col gap-2.5 text-[13px] leading-relaxed", className)}>
      {blocks.map((b, i) => {
        // The block list is static per template, so position is a fine key.
        const key = `${i}:${b.type}`;
        switch (b.type) {
          case "heading":
            return (
              <div
                key={key}
                className={cn(
                  "font-semibold text-balance",
                  b.level <= 2 ? "mt-1 text-sm" : "text-[13px]",
                )}
              >
                <Inline text={b.text} />
              </div>
            );
          case "paragraph":
            return (
              <p key={key}>
                {b.lines.map((line, j) => (
                  <Fragment key={`${j}:${line}`}>
                    {j > 0 && <br />}
                    <Inline text={line} />
                  </Fragment>
                ))}
              </p>
            );
          case "list": {
            const Tag = b.ordered ? "ol" : "ul";
            return (
              <Tag
                key={key}
                className={cn(
                  "space-y-0.5 pl-5 marker:text-muted-foreground/70",
                  b.ordered ? "list-decimal" : "list-disc",
                )}
              >
                {b.items.map((item, j) => (
                  <li key={`${j}:${item}`} className="pl-0.5">
                    <Inline text={item} />
                  </li>
                ))}
              </Tag>
            );
          }
          case "tag":
            return (
              <div key={key} className="font-mono text-[11px] text-muted-foreground">
                {b.text}
              </div>
            );
          case "rule":
            return <hr key={key} className="border-border/60" />;
          case "slot":
            return (
              <div key={key}>
                <SlotChip
                  index={b.index}
                  count={slotCount}
                  examples={slots?.slots[b.index]?.examples}
                  loading={loading}
                />
              </div>
            );
        }
      })}
    </div>
  );
}

/** Rough token count from length — about four characters per token. */
export function estimateTokens(text: string): number {
  return Math.ceil(text.length / 4);
}

